fn build_optional_member_path(expr: &Expr) -> Option<String> {
    let mut parts: Vec<String> = vec![];
    let mut current = expr;

    loop {
        match current {
            Expr::OptChain(opt_chain) => {
                if let OptChainBase::Member(member) = &*opt_chain.base {
                    match &member.prop {
                        MemberProp::Ident(ident) => {
                            parts.insert(0, ident.sym.to_string());
                        }
                        _ => return None, // Computed property
                    }
                    current = &member.obj;
                } else {
                    break;
                }
            }
            Expr::Member(member) => {
                match &member.prop {
                    MemberProp::Ident(ident) => {
                        parts.insert(0, ident.sym.to_string());
                    }
                    _ => return None, // Computed property
                }
                current = &member.obj;
            }
            _ => break,
        }
    }

    if let Expr::Ident(ident) = current {
        parts.insert(0, ident.sym.to_string());
        return Some(parts.join("."));
    }

    None
}
